    "assertion": "forall action_response: !contains(response, discord_uid) && !contains(response, email)",
    "severity": "MEDIUM",
    "covers": "SG-005",
    "reachability": {
      "classification": "external-reachable",
      "entry_points": [
        "HTTP",
        "ServerAction"
      ],
      "attacker_controlled": true,
      "bug_bounty_scope": "in-scope"
    },
    "exploitability": "external-attack",
    "code_scope": {
      "locations": [
        {
          "file": "src/app/oauth/userinfo/route.ts",
          "symbol": "GET",
          "line_range": {
            "start": 11,
            "end": 41
          },
          "role": "primary",
          "note": "Intentionally returns discord_id (line 39) in userinfo response per OAuth spec. This is by design for the OAuth userinfo endpoint."
        },
        {
          "file": "src/lib/actions/members.ts",
          "symbol": "registerNewMember",
          "line_range": {
            "start": 235,
            "end": 327
